foundation.question_text:
Find the coordinates of the point on $y = x^2 - x + 2$ where the tangent is parallel to the line $y = 3x - 7$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, x=0.7cm, y=0.35cm]
\draw[->] (-3.2,0) -- (5.8,0) node[right] {$x$};
\draw[->] (0,-8.5) -- (0,9.5) node[above] {$y$};
\foreach \x in {-2,2,4} {
  \draw (\x,0.3) -- (\x,-0.3) node[below, font=\scriptsize] {$\x$};
}
\foreach \y in {-8,-6,-4,-2,2,4,6,8} {
  \draw (0.2,\y) -- (-0.2,\y) node[left, font=\scriptsize] {$\y$};
}
\node[below left, font=\scriptsize] at (0,0) {$0$};
\draw[thick, blue, <->, domain=-2:3, samples=50, smooth, variable=\x] plot ({\x}, {\x*\x - \x + 2});
\draw[thick, red, <->, domain=-0.33:5, samples=20, smooth, variable=\x] plot ({\x}, {3*\x - 7});
\node[blue, above left, font=\small] at (-0.5,3) {$y = x^2 - x + 2$};
\node[red, below right, font=\small] at (3.2,2.6) {$y = 3x - 7$};
\end{tikzpicture}
[/tikz]

development.question_text:
Find the coordinates of the point on $y = 4x - x^2$ where the tangent is parallel to the line $2x + y - 8 = 0$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, x=0.7cm, y=0.35cm]
\draw[->] (-1.8,0) -- (6.8,0) node[right] {$x$};
\draw[->] (0,-5.8) -- (0,9.8) node[above] {$y$};
\foreach \x in {-1,1,2,3,4,5,6} {
  \draw (\x,0.3) -- (\x,-0.3) node[below, font=\scriptsize] {$\x$};
}
\foreach \y in {-4,-2,2,4,6,8} {
  \draw (0.2,\y) -- (-0.2,\y) node[left, font=\scriptsize] {$\y$};
}
\node[below left, font=\scriptsize] at (0,0) {$0$};
\draw[thick, blue, <->, domain=-1:5, samples=50, smooth, variable=\x] plot ({\x}, {4*\x - \x*\x});
\draw[thick, red, <->, domain=-0.5:6.5, samples=20, smooth, variable=\x] plot ({\x}, {-2*\x + 8});
\node[blue, above, font=\small] at (2,4.3) {$y = 4x - x^2$};
\node[red, above right, font=\small] at (3.5,1.5) {$2x + y - 8 = 0$};
\end{tikzpicture}
[/tikz]
